PRAGMA foreign_keys=ON;
CREATE TABLE patients(patient_id TEXT PRIMARY KEY, given_name TEXT NOT NULL, family_name TEXT NOT NULL, date_of_birth TEXT NOT NULL, recorded_sex TEXT, deceased TEXT NOT NULL CHECK(deceased IN ('true','false')), death_timestamp TEXT);
CREATE TABLE healthcare_professionals(professional_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, role TEXT, specialty TEXT);
CREATE TABLE hospital_units(unit_id TEXT PRIMARY KEY, unit_name TEXT NOT NULL, unit_type TEXT NOT NULL);
CREATE TABLE icd9_dictionary(icd9_code TEXT PRIMARY KEY, official_title TEXT NOT NULL, description TEXT, disease_category TEXT);
CREATE TABLE admissions(admission_id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(patient_id), admission_timestamp TEXT NOT NULL,admission_type TEXT NOT NULL,status TEXT NOT NULL,presenting_complaint TEXT,attending_professional_id TEXT REFERENCES healthcare_professionals(professional_id));
CREATE TABLE triage_assessments(triage_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),assessed_at TEXT NOT NULL,professional_id TEXT REFERENCES healthcare_professionals(professional_id),priority INTEGER CHECK(priority BETWEEN 1 AND 5),chief_complaint TEXT,heart_rate_bpm INTEGER,temperature_c REAL);
CREATE TABLE clinical_notes(note_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),professional_id TEXT REFERENCES healthcare_professionals(professional_id),note_timestamp TEXT NOT NULL,note_type TEXT NOT NULL,note_text TEXT);
CREATE TABLE diagnostic_orders(order_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),ordered_at TEXT NOT NULL,ordering_professional_id TEXT REFERENCES healthcare_professionals(professional_id),order_type TEXT,requested_test TEXT,status TEXT);
CREATE TABLE diagnostic_examinations(examination_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),order_id TEXT NOT NULL REFERENCES diagnostic_orders(order_id),performed_at TEXT NOT NULL,result_at TEXT,professional_id TEXT REFERENCES healthcare_professionals(professional_id),examination_type TEXT,examination_name TEXT,result_text TEXT);
CREATE TABLE radiology_examinations(radiology_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),examination_id TEXT NOT NULL UNIQUE REFERENCES diagnostic_examinations(examination_id),modality TEXT,body_region TEXT,started_at TEXT,ended_at TEXT,performing_professional_id TEXT REFERENCES healthcare_professionals(professional_id));
CREATE TABLE radiology_reports(report_id TEXT PRIMARY KEY,radiology_id TEXT NOT NULL REFERENCES radiology_examinations(radiology_id),reported_at TEXT,radiologist_id TEXT REFERENCES healthcare_professionals(professional_id),findings TEXT,impression TEXT,report_status TEXT);
CREATE TABLE surgical_procedures(procedure_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),procedure_name TEXT,surgeon_id TEXT REFERENCES healthcare_professionals(professional_id),started_at TEXT,ended_at TEXT,location_label TEXT,procedure_status TEXT);
CREATE TABLE unit_stays(stay_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),unit_id TEXT NOT NULL REFERENCES hospital_units(unit_id),entry_timestamp TEXT NOT NULL,exit_timestamp TEXT, CHECK(exit_timestamp IS NULL OR exit_timestamp >= entry_timestamp));
CREATE TABLE diagnoses(diagnosis_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES admissions(admission_id),icd9_code TEXT NOT NULL REFERENCES icd9_dictionary(icd9_code),diagnosis_role TEXT NOT NULL,recorded_at TEXT,diagnosing_professional_id TEXT REFERENCES healthcare_professionals(professional_id));
CREATE UNIQUE INDEX idx_one_primary_per_admission ON diagnoses(admission_id) WHERE diagnosis_role = 'PRIMARY';
CREATE TABLE discharge_records(discharge_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL UNIQUE REFERENCES admissions(admission_id),discharge_timestamp TEXT NOT NULL,disposition TEXT,discharging_professional_id TEXT REFERENCES healthcare_professionals(professional_id),condition_at_discharge TEXT);
CREATE INDEX idx_admissions_patient ON admissions(patient_id);
CREATE INDEX idx_stays_admission ON unit_stays(admission_id);
CREATE INDEX idx_diagnoses_admission ON diagnoses(admission_id);
CREATE INDEX idx_notes_admission ON clinical_notes(admission_id);
